// Rule L3b: two selections over one call become ONE call statement with a variable per output.
/// @asset Path(Game, "Functions/MF_MgSplit")
extern void MF_MgSplit(float2 UV, out float3 Head, out float Tail);

/// @name DreamShaderTests/Migrate/M_MgSelectShared
export void M_MgSelectShared(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Alpha = 0;
    float2 uv = UE.TexCoord(Index = 0);
    float3 MF_MgSplit_Head;
    float MF_MgSplit_Tail;
    MF_MgSplit(uv, Head = MF_MgSplit_Head, Tail = MF_MgSplit_Tail);
    // first use
    Color = MF_MgSplit_Head;
    // second use of the same call
    Alpha = MF_MgSplit_Tail;
    Base.EmissiveColor = Color;
    Base.Opacity = Alpha;
}
